import{_ as e,o,c as r,a5 as a}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"在 Spring Boot 中实现分页查询和字段过滤","description":"","frontmatter":{"title":"在 Spring Boot 中实现分页查询和字段过滤","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/在 Spring Boot 中实现分页查询和字段过滤.md","filePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/在 Spring Boot 中实现分页查询和字段过滤.md"}'),s={name:"posts/java快速入门/第五部分：数据库/02-MyBatis/在 Spring Boot 中实现分页查询和字段过滤.md"};function l(i,t,g,n,p,u){return o(),r("div",null,[...t[0]||(t[0]=[a("<div><p><strong>1. 引入依赖</strong> 首先，确保项目中已经引入了 MyBatis-Plus 和 Spring Boot 相关依赖： &lt;dependency&gt; &lt;groupId&gt;com.baomidou&lt;/groupId&gt; &lt;artifactId&gt;mybatis-plus-boot-starter&lt;/artifactId&gt; &lt;version&gt;3.4.3.4&lt;/version&gt; &lt;/dependency&gt;</p><p><strong>2. 创建分页和过滤的查询接口</strong> 以 BusinessService 为例，我们创建一个分页查询接口方法： public interface BusinessService&lt;T&gt; extends IService&lt;T&gt; { IPage&lt;T&gt; listPage(IPage&lt;T&gt; page, Wrapper&lt;T&gt; queryWrapper); } 这个接口方法定义了分页查询逻辑，接收 IPage&lt;T&gt;（分页对象）和 Wrapper&lt;T&gt;（查询条件）作为参数。</p><p><strong>3. 编写分页和字段过滤的控制器方法</strong> 假设我们有一个 MonitorModelController，其中的 list 方法提供分页和关键字过滤的功能。 @RestController @RequestMapping(&quot;/monitor&quot;) public class MonitorModelController { @Autowired private MonitorModelService monitorModelService;</p><p>@ApiOperation(&quot;查询列表&quot;) @GetMapping(&quot;/list&quot;) public R&lt;PageResult&lt;MonitorModelVO&gt;&gt; list( @RequestParam(value = &quot;pageNum&quot;, defaultValue = &quot;1&quot;) Long pageNum, @RequestParam(value = &quot;pageSize&quot;, defaultValue = &quot;10&quot;) Long pageSize, @RequestParam(value = &quot;keyword&quot;, required = false) String keyword) { // 1. 创建分页对象 Page&lt;MonitorModel&gt; pageRequest = new Page&lt;&gt;(pageNum, pageSize); // 2. 构造查询条件 QueryWrapper&lt;MonitorModel&gt; queryWrapper = new QueryWrapper&lt;&gt;(); if (StringUtils.isNotBlank(keyword)) { queryWrapper.lambda().like(MonitorModel::getName, keyword); // 假设需要查询的字段是 <code>name</code> } // 3. 执行分页查询 Page&lt;MonitorModel&gt; page = monitorModelService.page(pageRequest, queryWrapper); // 4. 数据转换 List&lt;MonitorModelVO&gt; results = page.getRecords().stream().map(record -&gt; { MonitorModelVO vo = new MonitorModelVO(); BeanUtils.copyProperties(record, vo); // 假设有其他信息需要填充，如关联的站点名称 vo.setSiteNames(siteManagerService.getSiteNames(record.getSiteId())); return vo; }).collect(Collectors.toList()); // 5. 返回结果 return R.ok(new PageResult&lt;&gt;(page.getTotal(), results)); } }</p><p><strong>4. 代码解释</strong></p><ol><li><strong>分页对象</strong>：使用 Page&lt;MonitorModel&gt; 创建分页请求对象 pageRequest，并设置当前页码和每页显示条数。</li><li><strong>QueryWrapper</strong>：使用 QueryWrapper 构造查询条件。如果前端传递了关键字 keyword，则对指定字段（如 name 字段）应用模糊查询。</li><li><strong>分页查询</strong>：调用 monitorModelService.page(pageRequest, queryWrapper) 方法，将分页对象和查询条件一并传递，获取分页数据。</li><li><strong>数据转换</strong>：将查询结果转换为目标 VO（值对象）列表。可以根据业务需求在此阶段填充其他字段（如关联字段）。</li><li><strong>返回结果</strong>：将分页总数和转换后的数据列表封装成 PageResult，并返回到前端。</li></ol><p><strong>5. 扩展：多字段过滤</strong> 如果需要添加更多的字段过滤条件，可以继续在 QueryWrapper 中添加其他条件： if(StringUtils.isNotBlank(keyword)) {￼ queryWrapper.lambda().like(MonitorModel::getName, keyword);￼}￼if(StringUtils.isNotBlank(status)) {￼ queryWrapper.lambda().eq(MonitorModel::getStatus, status); // 例如状态字段过滤}￼ <strong>6. 实现自定义返回结果类 PageResult</strong> PageResult 可以自定义一个类，用于返回分页数据，包含总记录数和当前页的数据列表： public class PageResult&lt;T&gt; { private Long total; private List&lt;T&gt; records; public PageResult(Long total, List&lt;T&gt; records) { this.total = total; this.records = records; } // Getter and Setter }</p><p><strong>7. 封装响应对象 R</strong> R 类通常用于统一API响应格式，可以定义为通用的响应格式类： public class R&lt;T&gt; { private Integer code; private String message; private T data; public static &lt;T&gt; R&lt;T&gt; ok(T data) { return new R&lt;&gt;(200, &quot;Success&quot;, data); } public R(Integer code, String message, T data) { this.code = code; this.message = message; this.data = data; } // Getter and Setter }</p><p><strong>总结</strong></p><ol><li><strong>分页和过滤查询</strong>：通过 MyBatis-Plus 的 Page 对象和 QueryWrapper 构造分页和条件查询。</li><li><strong>构建查询条件</strong>：可以使用 QueryWrapper 灵活地添加多字段的过滤条件，实现模糊查询或精确查询。</li><li><strong>结果封装</strong>：将结果转换为特定的 VO，并使用 PageResult 和 R 类统一返回结构。</li></ol></div>",1)])])}const M=e(s,[["render",l]]);export{c as __pageData,M as default};
